// Command chartfiles splits the output of "kustomize build config/default"
// into the files the Helm chart includes as they are: the CRDs and the RBAC
// (generated by controller-gen or written once in config/rbac), so the chart
// and the kustomize install cannot drift apart. Run it with make chart.
package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"

	"k8s.io/apimachinery/pkg/apis/meta/v1/unstructured"
	utilyaml "k8s.io/apimachinery/pkg/util/yaml"
	"sigs.k8s.io/yaml"
)

const header = "# Generated by \"make chart\" from config/; do not edit.\n"

var rbacKinds = map[string]bool{
	"ServiceAccount": true, "ClusterRole": true, "ClusterRoleBinding": true, "Role": true, "RoleBinding": true,
}

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: kustomize build config/default | chartfiles <chart files dir>")
		os.Exit(2)
	}
	if err := run(os.Stdin, os.Args[1]); err != nil {
		fmt.Fprintln(os.Stderr, "chartfiles:", err)
		os.Exit(1)
	}
}

func run(in io.Reader, dir string) error {
	var crds, rbac bytes.Buffer
	crds.WriteString(header)
	rbac.WriteString(header)
	r := utilyaml.NewYAMLReader(bufio.NewReader(in))
	for {
		doc, err := r.Read()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return err
		}
		var u unstructured.Unstructured
		if err := yaml.Unmarshal(doc, &u.Object); err != nil {
			return err
		}
		if u.Object == nil {
			continue
		}
		// Helm sets its own managed-by label.
		labels := u.GetLabels()
		delete(labels, "app.kubernetes.io/managed-by")
		u.SetLabels(labels)
		out := &rbac
		switch {
		case u.GetKind() == "CustomResourceDefinition":
			out = &crds
		case !rbacKinds[u.GetKind()]:
			continue
		}
		b, err := yaml.Marshal(u.Object)
		if err != nil {
			return err
		}
		out.WriteString("---\n")
		out.Write(b)
	}
	for name, b := range map[string][]byte{"crds.yaml": crds.Bytes(), "rbac.yaml": rbac.Bytes()} {
		if err := os.WriteFile(filepath.Join(dir, name), b, 0o644); err != nil { // #nosec G306 -- checked-in files
			return err
		}
	}
	return nil
}
